INSERT INTO `Partner` (`id`, `name`, `category`, `logoUrl`, `website`, `published`, `order`, `createdAt`) VALUES ('cmtmci3pd004jvpwqmrnmbl3d','Luz & Instante Fotografia','Fotografia',NULL,NULL,1,0,'2026-09-04 02:39:13.729'),('cmtmci3pp004kvpwq3abr64zi','Studio Frame Filmes','Filmagem',NULL,NULL,1,1,'2026-09-04 02:39:13.742'),('cmtmci3py004lvpwqjnuqk7vb','Doce Encanto Buffet','Buffet',NULL,NULL,1,2,'2026-09-04 02:39:13.750'),('cmtmci3q9004mvpwqupy63sei','Flor de Lis Decorações','Decoração',NULL,NULL,1,3,'2026-09-04 02:39:13.762'),('cmtmci3qg004nvpwqu9kyuemj','Ateliê Botânico','Flores',NULL,NULL,1,4,'2026-09-04 02:39:13.768'),('cmtmci3qo004ovpwqzgy373fy','DJ Marcelo Ramos','Música / DJ',NULL,NULL,1,5,'2026-09-04 02:39:13.777'),('cmtmci3qz004pvpwqfnx529lk','Doce Ponto Confeitaria','Doces e Bolo',NULL,NULL,1,6,'2026-09-04 02:39:13.787'),('cmtmci3rf004qvpwqsbytphrq','Convite Certo Papelaria','Convites',NULL,NULL,1,7,'2026-09-04 02:39:13.803'),('cmtmci3ro004rvpwq5dh9j10w','Espaço Villa Jardim','Espaço / Local',NULL,NULL,1,8,'2026-09-04 02:39:13.812'),('cmtmci3rx004svpwqhiafwipl','Bela Noiva Beauty','Beleza',NULL,NULL,1,9,'2026-09-04 02:39:13.822');
INSERT INTO `Post` (`id`, `authorId`, `content`, `imageUrl`, `published`, `createdAt`) VALUES ('cmtmbtmdo000bvprapsaqfzy4','cmtmbtmaj0000vpra5veej3x2','Gente, ainda em êxtase com o nosso casamento! A Amanda pensou em cada detalhe do cronograma, desde a montagem até o último brinde. No dia eu não precisei me preocupar com absolutamente nada, só aproveitar. Recomendo demais! 🤍',NULL,1,'2026-09-04 02:20:11.532'),('cmtmbtme2000dvprabm0kxkrc','cmtmbtmb00001vprawwl0odjt','Fechei com a Amanda faltando 4 meses pro casamento e foi a melhor decisão. Ela organizou os fornecedores, montou o cronograma do grande dia e ainda cuidou da minha lista de convidados. Tudo correu redondinho!',NULL,1,'2026-09-04 02:20:11.546'),('cmtmbtmes000fvpraw803nhjr','cmtmbtmba0002vpra3b1mcp26','O que mais me surpreendeu foi a calma que ela transmite. Mesmo quando choveu de última hora e precisamos mudar o local da cerimônia, ela resolveu tudo sem que eu nem percebesse a crise rolando. Gratidão eterna!',NULL,1,'2026-09-04 02:20:11.572'),('cmtmbtmf3000hvpra2aicmupt','cmtmbtmbj0003vpramekyh3kx','Casamos há duas semanas e até hoje recebo mensagens de convidados elogiando a organização. Isso é mérito 100% da Amanda e da equipe dela. O cortejo, os horários, tudo no tempo certo!',NULL,1,'2026-09-04 02:20:11.583'),('cmtmbtmfi000jvpra7b58x0l8','cmtmbtmbt0004vpra8ck2bb6g','Se tem uma coisa que não tem preço é chegar no seu próprio casamento e não precisar resolver nada. A Amanda cuidou até da planilha financeira com a gente, isso ajudou muito a manter o orçamento sob controle.',NULL,1,'2026-09-04 02:20:11.598'),('cmtmbtmfs000lvpratof1akxp','cmtmbtmc40005vpra55vpxex3','Alguém mais estava super perdida com a lista de fornecedores antes de contratar assessoria? Comigo foi assim, até a Amanda entrar e trazer indicações de confiança pra cada serviço. Facilitou muito nossa vida!',NULL,1,'2026-09-04 02:20:11.609'),('cmtmbtmg3000nvpraj9prqffd','cmtmbtmcb0006vpraa14xe28o','Nosso casamento foi em um espaço bem desafiador em termos de logística, e a visita técnica que ela fez antes evitou vários perrengues no dia. Profissionalismo do início ao fim.',NULL,1,'2026-09-04 02:20:11.619'),('cmtmbtmgh000pvpram5gybwsm','cmtmbtmck0007vpragkf989jr','Eu e meu marido nem imaginávamos como funcionava o cortejo, a ordem de entrada, essas coisas todas. A Amanda orientou os padrinhos e madrinhas certinho e no dia ninguém ficou perdido. Muito grata!',NULL,1,'2026-09-04 02:20:11.633'),('cmtmbtmgr000rvprap73zcgna','cmtmbtmcw0008vpra8wcex38a','O grupo de WhatsApp que ela cria pro casal facilita demais a comunicação durante o planejamento. Tirava dúvida na hora, sempre super solícita. Recomendo de olhos fechados!',NULL,1,'2026-09-04 02:20:11.643'),('cmtmbtmh0000tvprawlloe1zz','cmtmbtmd70009vprajhzhl7je','Depois do casamento ela ainda fez questão de fechar tudo com os fornecedores e nos entregar a planilha financeira consolidada. Cuidado do início ao pós-evento mesmo, amei trabalhar com ela.',NULL,1,'2026-09-04 02:20:11.652'),('cmtmci2vg000hvpwqwgzp78s8','cmtmci2sx0008vpwqmepz4ri4','Meninas, alguém mais super indecisa sobre o cronograma do dia? A Amanda me ajudou a organizar cada minuto, desde a hora de acordar até o último brinde. Recomendo demais essa etapa de planejamento!',NULL,1,'2026-09-04 02:39:12.653'),('cmtmci2vq000jvpwqq8u60pjl','cmtmci2t70009vpwq2grbxvyx','Semana que vem é meu casamento e estou tão tranquila graças à assessoria da Amanda. Antes eu vivia ansiosa pensando em mil detalhes, agora sei que está tudo nas mãos certas!',NULL,1,'2026-09-04 02:39:12.662'),('cmtmci2w2000lvpwq4yeopp6m','cmtmci2tj000avpwq97w7v25x','Casei em outubro e até hoje penso em como a equipe dela conseguiu resolver um imprevisto com o buffet sem que eu soubesse na hora. Só fiquei sabendo depois, no dia seguinte!',NULL,1,'2026-09-04 02:39:12.675'),('cmtmci2wi000nvpwq51tl6ohu','cmtmci2tt000bvpwqi6hhzlwn','Quem mais amou a ideia do grupo exclusivo no WhatsApp? Facilitou muito tirar dúvidas rápidas durante o planejamento, sem ficar esperando retorno de e-mail.',NULL,1,'2026-09-04 02:39:12.690'),('cmtmci2wy000pvpwqkshin0aa','cmtmci2u3000cvpwquahi5iha','Gente, a visita técnica que ela fez no espaço do nosso casamento evitou um perrengue enorme com a logística de fornecedores. Sem isso, ia dar ruim no dia!',NULL,1,'2026-09-04 02:39:12.706'),('cmtmci2xe000rvpwq2lpu7kgt','cmtmci2ud000dvpwqzx7y9z9d','Fechei a assessoria completa e recomendo muito pra quem tá naquela fase de contratar fornecedor atrás de fornecedor sem saber por onde começar.',NULL,1,'2026-09-04 02:39:12.723'),('cmtmci2xw000tvpwqfvnrr434','cmtmci2uq000evpwq7n6y60e6','O cortejo do nosso casamento tinha bastante gente (padrinhos, daminhas, pajem) e achei que ia ser um caos, mas ficou tudo super organizado no ensaio antes do grande dia.',NULL,1,'2026-09-04 02:39:12.741'),('cmtmci2yc000vvpwq5dtbqasy','cmtmci2v1000fvpwq4nrkzdxw','Amei ter recebido a planilha financeira consolidada no final. Deu pra ver exatamente onde foi cada centavo do orçamento do casamento, sem susto nenhum.',NULL,1,'2026-09-04 02:39:12.757');
