INSERT INTO `SiteSettings` (`id`, `heroTitle`, `heroSubtitle`, `aboutText`, `instagramUrl`, `whatsappNumber`, `email`) VALUES (1,'Amanda Alcântara','Assessoria intencional, estratégica e personalizada para quem deseja viver o grande dia.','Cuido de cada detalhe da sua cerimônia com carinho, organização e experiência, para que você viva o seu grande dia com leveza — do planejamento ao último brinde.','https://www.instagram.com/aamandacerimonial/','+55 48 8444-8087','');
INSERT INTO `TeamMember` (`id`, `name`, `role`, `bio`, `photoUrl`, `published`, `order`, `createdAt`, `updatedAt`) VALUES ('cmtmbtlwu0001vpqabwjclux9','Amanda Alcântara','Cerimonialista','Edite esta bio no painel admin em Equipe.','/fotos/amanda/direcionando.jpg',1,0,'2026-09-04 02:20:10.927','2026-09-04 02:39:12.118'),('cmtmci3nt004evpwq0mga9tsx','Rafael Menezes','Filmmaker','Responsável por eternizar cada momento em vídeo, com um olhar cinematográfico e discreto durante toda a celebração.','https://api.dicebear.com/9.x/notionists-neutral/svg?seed=Rafael%20Menezes&backgroundColor=f1e9e0',1,10,'2026-09-04 02:39:13.673','2026-09-04 02:39:13.992'),('cmtmci3o5004fvpwq12nicyv1','Isabela Ferraz','Ensaio e Direção','Conduz o ensaio do cortejo e a direção do roteiro da cerimônia, garantindo que todo mundo saiba exatamente a hora certa de entrar.','https://api.dicebear.com/9.x/notionists-neutral/svg?seed=Isabela%20Ferraz&backgroundColor=f1e9e0',1,11,'2026-09-04 02:39:13.686','2026-09-04 02:39:14.008'),('cmtmci3og004gvpwqcb9jtlgn','Lucas Andrade','Gerenciamento de Cronogramas','Monta e acompanha o cronograma oficial do evento, do horário de montagem ao encerramento, alinhando todos os fornecedores.','https://api.dicebear.com/9.x/notionists-neutral/svg?seed=Lucas%20Andrade&backgroundColor=f1e9e0',1,12,'2026-09-04 02:39:13.696','2026-09-04 02:39:14.022'),('cmtmci3on004hvpwqeo8w68q9','Fernanda Vieira','Supervisão no Dia do Evento','No grande dia, cuida de cada detalhe operacional para que os noivos só precisem aproveitar a festa.','https://api.dicebear.com/9.x/notionists-neutral/svg?seed=Fernanda%20Vieira&backgroundColor=f1e9e0',1,13,'2026-09-04 02:39:13.703','2026-09-04 02:39:14.032'),('cmtmci3ox004ivpwqnq4sbmfg','Camila Rezende','Planejamento e Design de Eventos','Desenvolve o conceito visual do evento, alinhando decoração, ambientação e identidade do casal a cada detalhe.','https://api.dicebear.com/9.x/notionists-neutral/svg?seed=Camila%20Rezende&backgroundColor=f1e9e0',1,14,'2026-09-04 02:39:13.713','2026-09-04 02:39:14.039');
INSERT INTO `Testimonial` (`id`, `clientName`, `eventType`, `quote`, `rating`, `photoUrl`, `published`, `order`, `createdAt`, `updatedAt`) VALUES ('cmtmbtlwj0000vpqa8ltuni8f','Exemplo: Ana & João','Casamento','Este é um depoimento de exemplo. Edite ou substitua pelo depoimento real de um cliente no painel admin.',5,NULL,1,0,'2026-09-04 02:20:10.915','2026-09-04 02:20:10.915'),('cmtmbtmyz004ovpra017g3ypj','Noiva (via WhatsApp)','Casamento','Oi Amanda, eu agradeço você por todo cuidado, carinho e dedicação para o nosso sonho realizado. Tivemos um dia muito lindo e nos divertimos muito. ❤️',5,NULL,1,0,'2026-09-04 02:20:12.299','2026-09-04 02:20:12.299'),('cmtmci2ly0000vpwqhozdf68j','Renata & Thiago','Casamento','A Amanda transformou o que seria um caos de última hora em um dia tranquilo. Confiamos cegamente e não foi à toa — cada detalhe saiu exatamente como planejado.',5,NULL,1,1,'2026-09-04 02:39:12.310','2026-09-04 02:39:12.310'),('cmtmci2mf0001vpwq7wp1s0cw','Vanessa Prado','Debutante (15 anos)','Contratamos a assessoria pra festa de 15 anos da minha filha e foi surpreendente ver o nível de organização. Os convidados nem perceberam a logística por trás, só aproveitaram a festa.',5,NULL,1,1,'2026-09-04 02:39:12.328','2026-09-04 02:39:12.328'),('cmtmci2mo0002vpwqyjvpsc68','Carla & Eduardo','Casamento','O que mais valorizamos foi a curadoria de fornecedores. Cada indicação da Amanda era certeira, e isso economizou muito tempo de pesquisa pra gente.',5,NULL,1,1,'2026-09-04 02:39:12.337','2026-09-04 02:39:12.337'),('cmtmci2my0003vpwq4ju1ukgp','Priscila Andrade','Aniversário','Simplesmente impecável. A supervisão no dia do evento foi tão discreta e eficiente que eu esqueci que existia uma logística inteira rolando por trás.',5,NULL,1,1,'2026-09-04 02:39:12.346','2026-09-04 02:39:12.346'),('cmtmci2nb0004vpwqmt5x1t79','Marcos & Letícia','Casamento','Fizemos um casamento em um espaço com bastante desafio logístico e a Amanda resolveu tudo com uma calma admirável. Recomendamos de olhos fechados.',5,NULL,1,1,'2026-09-04 02:39:12.359','2026-09-04 02:39:12.359'),('cmtmci2nn0005vpwqz6uj4so1','Tatiane Ribeiro','Batizado','Contratei pra organizar o batizado do meu filho e me surpreendi com o nível de cuidado, mesmo sendo um evento menor. Atenção total aos detalhes.',5,NULL,1,1,'2026-09-04 02:39:12.372','2026-09-04 02:39:12.372'),('cmtmci2oa0006vpwqe0fsfsgk','Gustavo & Amanda P.','Casamento','Ela cuidou de tudo, desde o cronograma até o pós-evento, fechando contas com fornecedores. A gente só teve que aparecer e curtir o nosso dia.',5,NULL,1,1,'2026-09-04 02:39:12.395','2026-09-04 02:39:12.395'),('cmtmci2os0007vpwq3dfhwcb1','Isabela Martins','Evento corporativo','Contratamos pra um evento corporativo grande e a coordenação foi impecável, com todos os horários e protocolos muito bem alinhados com nossa equipe.',4,NULL,1,1,'2026-09-04 02:39:12.413','2026-09-04 02:39:12.413');
SET FOREIGN_KEY_CHECKS=1;
